-- export 1/3: live_markets full (small mirror table), server-side CSV
SET statement_timeout TO '120s';
\copy (SELECT market_id, asset, question, end_time_est, current_yes_price, current_no_price, current_spread, volume_5min, price_velocity, last_updated, yes_token_id, no_token_id, trading_status, accepting_orders, resolution_status, final_outcome, resolved_at, resolution_checked_at, resolution_source, underlying_price, condition_id, slug, end_date, clob_token_id, clob_token_down_id, status, current_price_up, current_price_down, created_at, updated_at, volume_status, strike_value, strike_source, strike_effective_at, strike_received_at, oracle_price, binance_price, strike_observed_at, market_start_at, market_end_at, settlement_price_source FROM live_markets ORDER BY market_id) TO '/tmp/canonical_live_markets.csv' WITH (FORMAT CSV, HEADER)
